1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /**
30	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
31	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
32	     */
33	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
34	        if (owner == null) {
35	            return null;
36	        }
37	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
38	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
39	    }
40	
41	    /**
42	     * Derives the owner's locality from its city using the fixed city-to-region table
43	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD, see {@link Owner#regionForCity(String)}).
44	     * Returns the canonical region string, or {@code 'UNKNOWN'} when the city has no known region.
45	     */
46	    default String locality(Owner owner) {
47	        if (owner == null) {
48	            return null;
49	        }
50	        String region = Owner.regionForCity(owner.getCity());
51	        return region != null ? region : "UNKNOWN";
52	    }
53	
54	    /**
55	     * Returns the owner's numeric membership level, assigned on creation. The level starts at
56	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
57	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
58	     */
59	    default Integer membershipLevel(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        int level = 1;
64	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
65	        if (hasEmail) {
66	            level++;
67	        }
68	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
69	        if (noNamesakes) {
70	            level++;
71	        }
72	        return Math.min(level, 3);
73	    }
74	
75	    /**
76	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
77	     * last two digits of the registrationDate year, e.g. {@code 'SMI-0007-M26'}. Returns
78	     * {@code null} when the owner has no customer code or registration date.
79	     */
80	    default String membershipNumber(Owner owner) {
81	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
82	            return null;
83	        }
84	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
85	    }
86	
87	    /**
88	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
89	     */
90	    default String displayName(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        return owner.getLastName() + ", " + owner.getFirstName();
95	    }
96	
97	    /**
98	     * Returns the owner's initials as the upper-cased first letters of firstName and
99	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
100	     */
101	    default String initials(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
106	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
107	    }
108	
109	    Owner toOwner(OwnerDto ownerDto);
110	
111	    @Mapping(target = "id", ignore = true)
112	    @Mapping(target = "pets", ignore = true)
113	    Owner toOwner(OwnerFieldsDto ownerDto);
114	
115	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
116	
117	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
118	
119	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
120	        OwnerPageDto ownerPageDto = new OwnerPageDto();
121	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
122	        ownerPageDto.setPage(ownerPage.getNumber());
123	        ownerPageDto.setSize(ownerPage.getSize());
124	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
125	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
126	        return ownerPageDto;
127	    }
128	}
